// 1. Obtener el path original desde el body
let originalPath = $json.body?.path || "";

// 2. Si el path no está vacío, procesarlo
if (originalPath) {
  originalPath = originalPath.trim();

  // Caso A: Formato Markdown [texto](ruta) o envuelto en paréntesis (ruta)
  const markdownMatch = originalPath.match(/\((.*?)\)/);
  if (markdownMatch) {
    originalPath = markdownMatch[1].trim();
  } 
  // Caso B: Envuelto en corchetes simples [ruta]
  else if (originalPath.startsWith('[') && originalPath.endsWith(']')) {
    originalPath = originalPath.slice(1, -1).trim();
  }

  // Limpieza final por seguridad (quita comillas simples o dobles residuales)
  originalPath = originalPath.replace(/['"]/g, '').trim();
}

// 3. Devolver el objeto modificado manteniendo la estructura completa de $json
return {
  ...$json,
  body: {
    ...$json.body,
    path: originalPath
  }
};

